QJsonObject InitializeNode(const QString &root,const QString &programs,const QString &address,int port,const QString &dataDirectory){PrivateDirectory(root);Require(!QFile::exists(root+"/node.json"),"Node already initialized; reuse its existing configuration");Address(address,true);Port(port);Require(QDir::isAbsolutePath(dataDirectory) && QDir::cleanPath(dataDirectory)==dataDirectory,"Use an absolute local data directory");const auto node=QString::fromLatin1(Token().left(24));CreateCertificate(root,"getdaq-node-"+node);Write(root+"/agent.token",Token()+'\n');QJsonObject config{{"schema",1},{"kind","getdaq.node-agent"},{"node_id",node},{"root",root},{"program_directory",QDir(programs).absolutePath()},{"data_directory",dataDirectory},{"bind",address},{"port",port},{"credential_file",root+"/agent.token"},{"tls_certificate",root+"/tls.crt"},{"tls_key",root+"/tls.key"}};Write(root+"/node.json",Json(config));const auto code=QString::fromLatin1(Token().left(24));QJsonObject invitation{{"schema",1},{"node_id",node},{"url",QString("https://%1:%2").arg(address).arg(port)},{"certificate_sha256",CertificateFingerprint(root+"/tls.crt")},{"pairing_code",code},{"expires_ms",QDateTime::currentMSecsSinceEpoch()+15*60*1000}};Write(root+"/pairing.json",Json(invitation));return config;}
void RenewNodePairing(const QString &configuration){const auto config=Parse(Read(configuration));const auto root=config["root"].toString();PrivateDirectory(root);Require(!QFile::exists(root+"/master.json"),"An already paired node needs explicit master migration, not a new pairing code");const auto invitation=QJsonObject{{"schema",1},{"node_id",config["node_id"]},{"url",QString("https://%1:%2").arg(config["bind"].toString()).arg(config["port"].toInt())},{"certificate_sha256",CertificateFingerprint(config["tls_certificate"].toString())},{"pairing_code",QString::fromLatin1(Token().left(24))},{"expires_ms",QDateTime::currentMSecsSinceEpoch()+15*60*1000}};Write(root+"/pairing.json",Json(invitation));}
NodeAgent::NodeAgent(const QString &configuration,QObject *parent):QObject(parent),fConfig(Parse(Read(configuration))),fServer(this){Require(fConfig["schema"].toInt()==1 && fConfig["kind"]=="getdaq.node-agent","Unsupported node configuration");fRoot=fConfig["root"].toString();PrivateDirectory(fRoot);Require(QFileInfo(configuration).absoluteFilePath()==fRoot+"/node.json","Node configuration must be inside its private root");fPrograms=fConfig["program_directory"].toString();fData=fConfig["data_directory"].toString();fNode=Id(fConfig["node_id"].toString());fCredential=Secret(fConfig["credential_file"].toString());fLock.reset(new QLockFile(fRoot+"/agent.lock"));Require(fLock->tryLock(0),"Another node agent owns this working directory");PrivateDirectory(fRoot+"/operations");PrivateDirectory(fRoot+"/instances");PrivateDirectory(fRoot+"/objects");for(const auto &name:QDir(fRoot+"/operations").entryList({"*.json"},QDir::Files)){const auto path=fRoot+"/operations/"+name;auto record=Parse(Read(path));if(record["phase"]=="accepted" || record["phase"]=="running"){record["phase"]="unknown";record["message"]="Node agent restarted. Prior operations are not replayed; inspect original instance state.";Write(path,Json(record));}}connect(&fServer,&HttpServer::RequestSignal,this,&NodeAgent::Handle);}
NodeAgent::~NodeAgent(){fServer.close();QThreadPool::globalInstance()->waitForDone();}
void NodeAgent::Start(){fServer.SetTls(fConfig["tls_certificate"].toString(),fConfig["tls_key"].toString());Require(fServer.listen(QHostAddress(Address(fConfig["bind"].toString(),true)),quint16(Port(fConfig["port"].toInt()))),"Cannot listen on node management port");}
QJsonObject NodeAgent::Pair(const QJsonObject &request){if(QFile::exists(fRoot+"/master.json")){const auto previous=Parse(Read(fRoot+"/master.json"));Require(previous["pairing_request_sha256"].toString()==Sha(Json(request)) && previous["pairing_ack_until_ms"].toDouble()>QDateTime::currentMSecsSinceEpoch(),"This node is already paired; a consumed code cannot enroll another master");return {{"schema",1},{"node_id",fNode},{"credential",QString::fromLatin1(fCredential)},{"paired",true}};}const auto invitation=Parse(Read(fRoot+"/pairing.json"));Require(invitation["expires_ms"].toDouble()>QDateTime::currentMSecsSinceEpoch() && Sha(request["pairing_code"].toString().toUtf8())==Sha(invitation["pairing_code"].toString().toUtf8()),"Pairing code is invalid or expired");Endpoint repository{request["repository_url"].toString(),Digest(request["repository_certificate_sha256"].toString()),request["repository_token"].toString().toLatin1()};Require(QUrl(repository.url).scheme()=="https","Remote repository pairing requires HTTPS");Require(Get(repository,"/v1/identity")["repository_id"].toString()==Digest(request["repository_id"].toString()),"Master repository identity differs");ExactSecret(fRoot+"/repository.token",repository.credential);QJsonObject master{{"repository_url",repository.url},{"certificate_sha256",repository.certificateSha256},{"repository_id",request["repository_id"]},{"credential_file",fRoot+"/repository.token"},{"pairing_request_sha256",Sha(Json(request))},{"pairing_ack_until_ms",invitation["expires_ms"]}};Write(fRoot+"/master.json",Json(master));Require(QFile::remove(fRoot+"/pairing.json"),"Cannot consume pairing invitation");return {{"schema",1},{"node_id",fNode},{"credential",QString::fromLatin1(fCredential)},{"paired",true}};}
QJsonObject NodeAgent::Inventory()const{QJsonArray addresses,programs,instances;for(const auto &address:QNetworkInterface::allAddresses())if(address.protocol()==QAbstractSocket::IPv4Protocol)addresses.append(address.toString());for(const auto &name:{"getdaq-ecc-server","getdaq-supervisor","getdaq-supervisor-query","getdaq-receiver"}){const auto path=QDir(fPrograms).filePath(name);QJsonObject entry{{"name",name},{"installed",QFileInfo(path).isExecutable()}};if(QFileInfo(path).isExecutable())entry["sha256"]=Sha(Read(path,256*1024*1024));programs.append(entry);}for(const auto &name:QDir(fRoot+"/instances").entryList({"*.json"},QDir::Files)){auto entry=Parse(Read(fRoot+"/instances/"+name));QJsonArray pids;for(const auto &process:FindLocalServiceProcesses(entry["program"].toString(),entry["config_file"].toString()))pids.append(double(process.pid));entry["actual_pids"]=pids;entry.remove("checked_files");entry.remove("plan");entry.remove("plan_bytes");instances.append(entry);}return {{"schema",1},{"node_id",fNode},{"protocol",1},{"addresses",addresses},{"program_directory",fPrograms},{"data_directory",fData},{"programs",programs},{"instances",instances}};}
QJsonObject NodeAgent::InstanceStatus(const QString &instance)const{const auto selected=Parse(Read(fRoot+"/instances/"+Id(instance)+".json"));const auto config=Parse(Read(selected["config_file"].toString()));QJsonArray pids;for(const auto &process:FindLocalServiceProcesses(selected["program"].toString(),selected["config_file"].toString()))pids.append(double(process.pid));Require(pids.size()==1,"Selected service does not have one matching live process");return {{"node_id",fNode},{"instance_id",instance},{"release_id",selected["release_id"]},{"group_sha256",selected["group_sha256"]},{"actual_pids",pids},{"identity",ServiceGet(config,"/v1/identity")},{"status",ServiceGet(config,"/v1/status")}};}
