QJsonObject NodeAgent::Activate(const QJsonObject &request,bool *effects){Progress(request,"Checking prepared service inputs");const auto instance=InstanceId(request),release=Digest(request["release_id"].toString()),directory=fRoot+"/deployments/"+release+'/'+instance;auto prepared=Parse(Read(directory+"/prepared.json"));Require(prepared["node_id"]==fNode && prepared["release_id"]==release && prepared["instance_id"]==instance,"Prepared instance identity differs");const auto program=prepared["program"].toString(),configFile=prepared["config_file"].toString();Require(QFileInfo(program).absolutePath()==fPrograms && Sha(Read(program,256*1024*1024))==prepared["program_sha256"].toString(),"Installed service executable changed");const auto hashes=prepared["checked_files"].toObject();for(auto it=hashes.begin();it!=hashes.end();++it)Require(Sha(Read(it.key(),64*1024*1024))==it.value().toString(),"A prepared input changed");const auto selectedFile=fRoot+"/instances/"+instance+".json";const QString previous=request["expected_previous"].toString();if(QFile::exists(selectedFile)){const auto selected=Parse(Read(selectedFile));Require(selected["release_id"].toString()==previous,"Selected deployment differs from expected previous version");if(selected["release_id"]!=release)Require(DeploymentInstanceReleased(selected),"Normally stop the previous instance, or use Review terminated group after inspecting hardware and data");}else Require(previous.isEmpty(),"Expected previous instance is missing");const auto config=Parse(Read(configFile));Progress(request,"Validating "+QFileInfo(program).fileName()+" configuration");Run(program,{"--config",configFile,"--check-config"});
    for(const auto &name:{QString("getdaq-ecc-server"),QString("getdaq-supervisor")})for(const auto &other:LocalServiceConfigurations(QDir(fPrograms).filePath(name))){if(other==configFile)continue;const auto otherConfig=Parse(Read(other));Require(otherConfig["port"]!=config["port"] || otherConfig["bind"]!=config["bind"],"Another service owns this control endpoint");if(name=="getdaq-ecc-server" && request["role"]=="ecc"){const auto currentTopology=Parse(Read(config["topology"].toObject()["path"].toString())),otherTopology=Parse(Read(otherConfig["topology"].toObject()["path"].toString()));QSet<QString> proxies;for(const auto &key:{"cobos","mutants"})for(const auto &node:currentTopology[key].toArray())proxies.insert(node.toObject()["node_proxy"].toString());for(const auto &key:{"cobos","mutants"})for(const auto &node:otherTopology[key].toArray())Require(!proxies.contains(node.toObject()["node_proxy"].toString()),"Another ECC already controls this board");}}
    auto processes=FindLocalServiceProcesses(program,configFile);if(processes.isEmpty()){Progress(request,"Starting "+QFileInfo(program).fileName());QTcpServer probe;Require(probe.listen(QHostAddress(config["bind"].toString()),quint16(config["port"].toInt())),"Control endpoint is already in use");probe.close();prepared["phase"]="starting";prepared["stopped"]=false;Write(selectedFile,Json(prepared));*effects=true;QProcess process;auto environment=QProcessEnvironment::systemEnvironment();environment.remove("GETDAQ_READBACK_WARNING_POLICY_FILE");if(QFile::exists(directory+"/readback-warning-policy.json"))environment.insert("GETDAQ_READBACK_WARNING_POLICY_FILE",directory+"/readback-warning-policy.json");process.setProcessEnvironment(environment);process.setProgram(program);process.setArguments({"--config",configFile});process.setWorkingDirectory(directory);process.setStandardOutputFile(directory+"/logs/service.log",QIODevice::Append);process.setStandardErrorFile(directory+"/logs/service.log",QIODevice::Append);qint64 pid=0;Require(process.startDetached(&pid),"Cannot launch prepared service");}
    Progress(request,QString("Verifying backend identity at %1:%2").arg(config["bind"].toString()).arg(config["port"].toInt()));QJsonObject identity;QString lastError;QElapsedTimer readiness;readiness.start();for(int i=0;i<30 && readiness.elapsed()<5000;++i){CheckOperation();try{identity=ServiceGet(config,"/v1/identity");if(request["role"]=="ecc")Require(identity["service_id"]==config["service_id"] && identity["snapshot_sha256"]==prepared["snapshot_sha256"] && identity["input_binding_sha256"]==prepared["input_binding_sha256"],"Actual ECC input identity differs");else Require(identity["agent_id"]==config["agent_id"] && identity["plan_sha256"]==prepared["plan_sha256"],"Actual receiving plan identity differs");lastError.clear();break;}catch(const std::exception &error){lastError=QString::fromUtf8(error.what());QThread::msleep(100);}}Require(lastError.isEmpty(),"Service identity not verified: "+lastError);prepared["phase"]="active";prepared["stopped"]=false;prepared["identity"]=identity;Write(selectedFile,Json(prepared));prepared.remove("checked_files");prepared.remove("plan");prepared.remove("plan_bytes");return prepared;}
QJsonObject NodeAgent::ReleaseTerminated(const QJsonObject &request,bool *effects) {
    Require(request["accepted_repair"].toBool(),"Explicit hardware-stop and data-preservation confirmation required");
    const auto instance=InstanceId(request),path=fRoot+"/instances/"+instance+".json";auto selected=Parse(Read(path));
    Require(selected["release_id"]==request["release_id"],"Inspection release differs from selected instance");
    Require(selected["phase"]=="terminated-needs-inspection" || selected["phase"]=="released-after-inspection","Only a terminated instance can be released after inspection");
    const auto config=selected["config_file"].toString(),program=selected["program"].toString();
    Require(QFileInfo(program).absolutePath()==fPrograms,"Inspection target installation differs");
    Require(FindLocalServiceProcesses(program,config).isEmpty(),"Backend process is still active; inspection release refused");
    Require(FindLocalReceiverProcesses(QDir(fPrograms).filePath("getdaq-receiver"),config).isEmpty(),"Receiver child is still active; inspection release refused");
    if(DeploymentInstanceReleased(selected)){selected.remove("checked_files");selected.remove("plan");selected.remove("plan_bytes");return selected;}
    const QJsonObject receipt{{"kind","getdaq.inspected-deployment-release"},{"instance_id",instance},{"release_id",request["release_id"]},{"operation_id",request["operation_id"]},
        {"previous_phase",selected["phase"]},{"operator_confirmed_stopped",true},{"data_preserved",true},{"no_matching_processes",true},
        {"hardware_state_source","operator confirmation; not inferred from process exit"},{"time_utc",QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs)}};
    *effects=true;
    Write(QFileInfo(config).absolutePath()+"/inspection-release-"+Id(request["operation_id"].toString())+".json",Json(receipt),true);
    selected["inspection_release"]=receipt;selected["phase"]="released-after-inspection";selected["stopped"]=false;
    Write(path,Json(selected));selected.remove("checked_files");selected.remove("plan");selected.remove("plan_bytes");return selected;
}
QJsonObject NodeAgent::StopInstance(const QJsonObject &request,bool repair,bool *effects){const auto instance=InstanceId(request),path=fRoot+"/instances/"+instance+".json";auto selected=Parse(Read(path));Require(selected["release_id"]==request["release_id"],"Stop target release differs from selected instance");const auto configFile=selected["config_file"].toString(),program=selected["program"].toString();Require(QFileInfo(program).absolutePath()==fPrograms,"Stop target installation differs");const auto config=Parse(Read(configFile));auto processes=FindLocalServiceProcesses(program,configFile);const auto receivers=request["role"]=="receiver"?FindLocalReceiverProcesses(QDir(fPrograms).filePath("getdaq-receiver"),configFile):QVector<LocalServiceProcess>();if(!repair){if(processes.isEmpty())Require(selected["stopped"].toBool() && selected["phase"]=="stopped","Service is unavailable; cannot infer that its prior hardware/data session stopped. Inspect before changing deployment.");Require(receivers.isEmpty(),"Receiver processes are still active; finish acquisition first");if(!processes.isEmpty()){const auto identity=ServiceGet(config,"/v1/identity");if(request["role"]=="ecc")Require(identity["service_id"]==config["service_id"] && identity["snapshot_sha256"]==selected["snapshot_sha256"] && identity["input_binding_sha256"]==selected["input_binding_sha256"],"Stop target ECC identity differs");else Require(identity["agent_id"]==config["agent_id"] && identity["plan_sha256"]==selected["plan_sha256"],"Stop target receiver identity differs");const auto status=ServiceGet(config,"/v1/status");if(request["role"]=="ecc"){const auto controller=status["controller"].toObject();Require(!status["operation_active"].toBool() && !status["control_needs_reconciliation"].toBool() && !status["data_needs_reconciliation"].toBool() && !controller["outcome_unknown"].toBool() && !controller["needs_reconciliation"].toBool() && controller["state"].toInt()==1,"Return ECC to confirmed Idle before normal backend shutdown");}else{const auto lifecycle=status["lifecycle"].toObject();bool released=lifecycle["state"]=="fresh" && lifecycle["session_id"].toString().isEmpty() && lifecycle["receivers"].toArray().isEmpty();if(lifecycle["state"]=="stopped"){released=true;for(const auto &value:lifecycle["receivers"].toArray()){const auto receiver=value.toObject();released=released && receiver["reaped"].toBool() && receiver["seal_verified"].toBool() && receiver["exit_code"].toInt(-1)==0;}}Require(lifecycle.contains("needs_reconciliation") && !lifecycle["needs_reconciliation"].toBool() && released,"Receiving service has not completed its normal session finalization");}}}else Require(request["accepted_repair"].toBool(),"Explicit repair termination confirmation required");processes+=receivers;for(const auto &process:processes)if(SameLocalServiceProcess(process)){*effects=true;Require(!::kill(process.pid,SIGTERM),"Cannot signal selected instance");}for(int i=0;i<50;++i){bool remaining=false;for(const auto &process:processes)remaining=remaining||SameLocalServiceProcess(process);if(!remaining)break;QThread::msleep(100);}for(const auto &process:processes)Require(!SameLocalServiceProcess(process),"Process did not exit; it was not killed automatically");selected["phase"]=repair?"terminated-needs-inspection":"stopped";selected["stopped"]=!repair;Write(path,Json(selected));selected.remove("checked_files");selected.remove("plan");selected.remove("plan_bytes");return selected;}
